import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals. This exercise asks you not to use useMemo.

export interface User {
  id: number;
  name: string;
  team: string;
}

const USERS: User[] = [
  { id: 1, name: 'Asha Rao', team: 'Checkout' },
  { id: 2, name: 'Ben Ortiz', team: 'Search' },
  { id: 3, name: 'Chen Wei', team: 'Payments' }
];

let requests = 0;
let failNext = false;

// Fake users API. Treat it as given.
// - resolves the three users after 300ms
// - rejects once after failNextRequest() is called
export function fetchUsers(): Promise<User[]> {
  requests += 1;
  const shouldFail = failNext;
  failNext = false;
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (shouldFail) {
        reject(new Error('Users service unavailable'));
        return;
      }
      resolve(USERS.map((user) => ({ ...user })));
    }, 300);
  });
}

export function failNextRequest(): void {
  failNext = true;
}

export function requestCount(): number {
  return requests;
}

export type UsersState =
  | { status: 'loading' }
  | { status: 'success'; users: User[] }
  | { status: 'error'; message: string };

export type UsersContextValue = {
  state: UsersState;
  reload: () => void;
};

function useMemoized<T>(factory: () => T, deps: readonly unknown[]): T {
  // TODO (part 1): implement memoization without React's useMemo. Return the cached
  // value while every dependency is the same (compare with Object.is), and call
  // factory again only when a dependency or the number of dependencies changes.
  return factory();
}

// TODO (part 2): share one users request through this context.
const UsersContext = createContext<UsersContextValue | null>(null);

function UsersProvider({ children }: { children: React.ReactNode }) {
  // TODO (part 2): load the users once on mount with fetchUsers(), keep a UsersState,
  // expose { state, reload } through UsersContext, map a rejection to the error state,
  // ignore a response that arrives after a newer reload, and memoize the context value
  // with useMemoized so unrelated renders keep the same value.
  return <>{children}</>;
}

function useUsers(): UsersContextValue {
  const context = useContext(UsersContext);
  // TODO (part 2): throw a clear error when the hook is used outside <UsersProvider>.
  return context ?? { state: { status: 'loading' }, reload: () => {} };
}

function UserSummary() {
  const { state } = useUsers();
  if (state.status === 'loading') return <p className="status status--loading">Loading users…</p>;
  if (state.status === 'error') {
    return <p className="status status--error" role="alert">Could not load users: {state.message}</p>;
  }
  return <p className="user-count">{state.users.length} users</p>;
}

function UserList() {
  const { state } = useUsers();
  if (state.status !== 'success') return null;
  return (
    <ul className="user-list">
      {state.users.map((user) => (
        <li key={user.id} className="user-row">
          <span className="user-name">{user.name}</span>
          <span className="user-team">{user.team}</span>
        </li>
      ))}
    </ul>
  );
}

function UsersToolbar() {
  const { reload } = useUsers();
  return (
    <div className="toolbar">
      <button type="button" className="reload" onClick={reload}>Reload</button>
      <button type="button" className="fail-next" onClick={failNextRequest}>Fail next request</button>
      <span className="request-count">Requests: {requestCount()}</span>
    </div>
  );
}

const FRUITS = ['Apple', 'Banana', 'Mango', 'Orange', 'Grape', 'Melon'];
let computations = 0;

export default function App() {
  const [query, setQuery] = useState('');
  const [renders, setRenders] = useState(0);
  const visible = useMemoized(() => {
    computations += 1;
    const needle = query.trim().toLowerCase();
    return FRUITS.filter((fruit) => fruit.toLowerCase().includes(needle));
  }, [query]);

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">useMemo and Context from scratch</h1>
          <p className="subtitle">Part 1 memoizes a filter without useMemo. Part 2 serves API results through context.</p>
        </header>

        <section className="panel">
          <h2 className="panel-title">Part 1: useMemoized</h2>
          <input
            className="filter"
            value={query}
            placeholder="Filter fruits"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) => setQuery(event.target.value)}
          />
          <div className="toolbar">
            <button type="button" className="bump" onClick={() => setRenders((count) => count + 1)}>
              Re-render ({renders})
            </button>
            <span className="compute-count">Computed {computations} {computations === 1 ? 'time' : 'times'}</span>
          </div>
          <ul className="fruit-list">
            {visible.map((fruit) => (
              <li key={fruit} className="fruit-row">{fruit}</li>
            ))}
          </ul>
        </section>

        <section className="panel">
          <h2 className="panel-title">Part 2: context with API results</h2>
          <UsersProvider>
            <UserSummary />
            <UserList />
            <UsersToolbar />
          </UsersProvider>
        </section>
      </section>
    </main>
  );
}

