:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.main {
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  place-items: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 18px 18px 16px;
  display: grid;
  gap: 16px;
}

.header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.panel {
  display: grid;
  gap: 10px;
  padding: 12px;
  border-radius: 12px;
  border: 1px solid #1f2937;
}

.panel-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.filter {
  width: 100%;
  box-sizing: border-box;
  border-radius: 10px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 8px 12px;
  font-size: 14px;
  outline: none;
}

.filter:focus {
  border-color: #a3e635;
  box-shadow: 0 0 0 1px #a3e63533;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: #9ca3af;
}

.toolbar button {
  border-radius: 999px;
  border: 1px solid #a3e635;
  background: transparent;
  color: #a3e635;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.toolbar button:focus-visible {
  outline: 2px solid #a3e635;
  outline-offset: 2px;
}

.fruit-list,
.user-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}

.fruit-row,
.user-row {
  padding: 6px 10px;
  border-radius: 10px;
  border: 1px solid #1f2937;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 14px;
}

.user-team {
  font-size: 12px;
  color: #9ca3af;
}

.status,
.user-count {
  margin: 0;
  font-size: 13px;
}

.status--loading {
  color: #e5e7eb;
}

.status--error {
  color: #f97316;
}

.user-count {
  color: #9ca3af;
}
